WITH long_format AS (SELECT id, category, measure, val FROM (SELECT id, category, price, cost FROM products) src UNPIVOT (val FOR measure IN (price AS PRICE, cost AS COST_VAL))) SELECT CASE WHEN val >= 84 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, measure, APPROX_PERCENTILE(val, ARRAY(0.25, 0.5, 0.75)) AS val_quartiles, SUM(CASE WHEN measure = 'COST_VAL' THEN val ELSE 0 END) AS cost_val_val, COUNT_IF(measure = 'PRICE') AS price_events, PERCENTILE_APPROX(val, 0.95) AS val_p95, ROUND(AVG(val), 2) AS avg_val FROM long_format GROUP BY CASE WHEN val >= 84 THEN 'LARGE' ELSE 'SMALL' END, measure ORDER BY cost_val_val NULLS LAST;
